/// Returns the block that owns this global state ID.
pub fn block_of_state(state: u16) -> Option<&'static BlockDef> {
    let idx = BLOCKS.partition_point(|b| b.base_id <= state);
    if idx == 0 { return None; }
    let b = &BLOCKS[idx - 1];
    if state < b.base_id + b.state_count { Some(b) } else { None }
}

/// Finds a block by namespaced name, e.g. "minecraft:stone".
pub fn block_by_name(name: &str) -> Option<&'static BlockDef> {
    BLOCKS.iter().find(|b| b.name == name)
}
